const API_BASE_URL =
  process.env.NEXT_PUBLIC_API_BASE_URL || "http://localhost:5000";

export interface Pattern {
  id: string;
  identityId: string;
  cameraId: string;
  type: string;
  meanHour: number;
  stdHour: number;
  occurrences: number;
}

export interface Anomaly {
  id: string;
  identityId: string;
  cameraId: string;
  anomalyType: string;
  timestamp: string;
}

interface ApiResponse<T> {
  success: boolean;
  data: T;
  count?: number;
}

export async function getPatterns(): Promise<Pattern[]> {
  try {
    const response = await fetch(`${API_BASE_URL}/api/patterns`, {
      cache: "no-store",
      credentials: "include",
    });

    const data: ApiResponse<Pattern[]> = await response.json();
    return data.success ? data.data : [];
  } catch (error) {
    console.error("Failed to fetch patterns:", error);
    return [];
  }
}

export async function getAnomalies(): Promise<Anomaly[]> {
  try {
    const response = await fetch(`${API_BASE_URL}/api/patterns/anomalies`, {
      cache: "no-store",
      credentials: "include",
    });

    const data: ApiResponse<Anomaly[]> = await response.json();
    return data.success ? data.data : [];
  } catch (error) {
    console.error("Failed to fetch anomalies:", error);
    return [];
  }
}

export async function runPipeline(): Promise<{
  success: boolean;
  message: string;
}> {
  try {
    const response = await fetch(`${API_BASE_URL}/api/pipeline/run`, {
      method: "POST",
      credentials: "include",
    });

    return await response.json();
  } catch (error) {
    console.error("Failed to run pipeline:", error);
    return { success: false, message: "Pipeline execution failed" };
  }
}
