"use client";

import { useEffect, useState } from "react";

import { getPatterns } from "@/lib/api/patterns";
import { PatternTable } from "@/components/pattern-table";

/* ================= TYPES MATCH BACKEND ================= */

interface Pattern {
  id: string;

  identityId: string;
  cameraId: string;

  type: string;

  meanHour: number;
  stdHour: number;

  occurrences: number;
}

/* ======================================================= */

export default function PatternsPage() {
  const [patterns, setPatterns] = useState<Pattern[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [currentPage, setCurrentPage] = useState(1);

  /* ================= FETCH ================= */

  useEffect(() => {
    const fetchPatterns = async () => {
      setIsLoading(true);

      try {
        const data = await getPatterns();
        setPatterns(data);
      } catch (error) {
        console.error("Error fetching patterns:", error);
      } finally {
        setIsLoading(false);
      }
    };

    fetchPatterns();
  }, []);

  /* ================= METRICS ================= */

  const getPatternCounts = () => {
    return {
      regular: patterns.filter((p) => p.type === "regular").length,
      irregular: patterns.filter((p) => p.type === "irregular").length,
      anomalous: patterns.filter((p) => p.type === "anomalous").length,
    };
  };

  const getTotalOccurrences = () => {
    return patterns.reduce((sum, p) => sum + p.occurrences, 0);
  };

  const counts = getPatternCounts();

  /* ================= UI ================= */

  return (
    <div className="space-y-6 p-6">
      {/* ================= HEADER ================= */}

      <div>
        <h1 className="text-3xl font-bold text-white mb-2">Patterns</h1>

        <p className="text-gray-400">
          Behavioral patterns detected across identities and cameras
        </p>
      </div>

      {/* ================= PATTERN METRICS ================= */}

      <div className="grid grid-cols-4 gap-4">
        <div className="bg-[#222] border border-[#333] rounded-lg p-4">
          <p className="text-sm text-gray-400">Total Patterns</p>

          <p className="text-2xl font-bold text-white mt-1">
            {patterns.length}
          </p>
        </div>

        <div className="bg-[#222] border border-green-500/50 rounded-lg p-4">
          <p className="text-sm text-green-400">Regular</p>

          <p className="text-2xl font-bold text-green-400 mt-1">
            {counts.regular}
          </p>
        </div>

        <div className="bg-[#222] border border-yellow-500/50 rounded-lg p-4">
          <p className="text-sm text-yellow-400">Irregular</p>

          <p className="text-2xl font-bold text-yellow-400 mt-1">
            {counts.irregular}
          </p>
        </div>

        <div className="bg-[#222] border border-red-500/50 rounded-lg p-4">
          <p className="text-sm text-red-400">Anomalous</p>

          <p className="text-2xl font-bold text-red-400 mt-1">
            {counts.anomalous}
          </p>
        </div>
      </div>

      {/* ================= TOTAL OCCURRENCES ================= */}

      <div className="bg-[#222] border border-[#333] rounded-lg p-4">
        <p className="text-sm text-gray-400">Total Occurrences</p>

        <p className="text-3xl font-bold text-cyan-400 mt-2">
          {getTotalOccurrences()}
        </p>
      </div>

      {/* ================= TABLE ================= */}

      <PatternTable
        patterns={patterns}
        isLoading={isLoading}
        currentPage={currentPage}
        onPageChange={setCurrentPage}
      />
    </div>
  );
}
