"use client";

import { Card } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";

/* ================= TYPES MATCH BACKEND ================= */

export interface Pattern {
  id: string;

  identityId: string;
  cameraId: string;

  type: string;

  meanHour: number;
  stdHour: number;

  occurrences: number;
}

/* ======================================================= */

interface PatternTableProps {
  patterns: Pattern[];
  isLoading?: boolean;
  currentPage?: number;
  itemsPerPage?: number;
  onPageChange?: (page: number) => void;
}

export function PatternTable({
  patterns,
  isLoading = false,
  currentPage = 1,
  itemsPerPage = 10,
  onPageChange,
}: PatternTableProps) {
  const paginatedPatterns = patterns.slice(
    (currentPage - 1) * itemsPerPage,
    currentPage * itemsPerPage,
  );

  const totalPages = Math.ceil(patterns.length / itemsPerPage);

  const getPatternBadge = (patternType: string) => {
    switch (patternType) {
      case "regular":
        return "bg-green-500/20 text-green-400";
      case "irregular":
        return "bg-yellow-500/20 text-yellow-400";
      case "anomalous":
        return "bg-red-500/20 text-red-400";
      default:
        return "bg-gray-500/20 text-gray-400";
    }
  };

  /* ================= LOADING ================= */

  if (isLoading) {
    return (
      <Card className="bg-[#222] border-[#333]">
        <div className="p-6 space-y-4">
          {[...Array(5)].map((_, i) => (
            <Skeleton key={i} className="h-12 bg-[#333]" />
          ))}
        </div>
      </Card>
    );
  }

  /* ================= EMPTY ================= */

  if (patterns.length === 0) {
    return (
      <Card className="bg-[#222] border-[#333]">
        <div className="p-12 text-center">
          <p className="text-gray-400">No patterns found</p>
        </div>
      </Card>
    );
  }

  /* ================= TABLE ================= */

  return (
    <Card className="bg-[#222] border-[#333] overflow-hidden">
      <div className="overflow-x-auto">
        <table className="w-full">
          <thead>
            <tr className="border-b border-[#333] bg-[#1a1a1a]">
              <th className="px-6 py-3 text-left text-sm font-semibold text-gray-300">
                Identity ID
              </th>

              <th className="px-6 py-3 text-left text-sm font-semibold text-gray-300">
                Camera ID
              </th>

              <th className="px-6 py-3 text-left text-sm font-semibold text-gray-300">
                Pattern Type
              </th>

              <th className="px-6 py-3 text-right text-sm font-semibold text-gray-300">
                Mean Hour
              </th>

              <th className="px-6 py-3 text-right text-sm font-semibold text-gray-300">
                Std Dev
              </th>

              <th className="px-6 py-3 text-right text-sm font-semibold text-gray-300">
                Occurrences
              </th>
            </tr>
          </thead>

          <tbody>
            {paginatedPatterns.map((pattern) => (
              <tr
                key={pattern.id}
                className="border-b border-[#333] hover:bg-[#333]/50 transition-colors"
              >
                <td className="px-6 py-4 text-sm font-mono text-cyan-400">
                  {pattern.identityId}
                </td>

                <td className="px-6 py-4 text-sm text-gray-300">
                  {pattern.cameraId}
                </td>

                <td className="px-6 py-4 text-sm">
                  <Badge
                    className={`${getPatternBadge(pattern.type)} border-0 capitalize`}
                  >
                    {pattern.type}
                  </Badge>
                </td>

                <td className="px-6 py-4 text-sm text-gray-300 text-right">
                  {pattern.meanHour.toFixed(2)}h
                </td>

                <td className="px-6 py-4 text-sm text-gray-300 text-right">
                  {pattern.stdHour.toFixed(2)}h
                </td>

                <td className="px-6 py-4 text-sm text-gray-300 text-right font-semibold">
                  {pattern.occurrences}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* ================= PAGINATION ================= */}

      {totalPages > 1 && (
        <div className="px-6 py-4 border-t border-[#333] flex items-center justify-between">
          <p className="text-sm text-gray-400">
            Page {currentPage} of {totalPages}
          </p>

          <div className="flex gap-2">
            <button
              onClick={() => onPageChange?.(Math.max(1, currentPage - 1))}
              disabled={currentPage === 1}
              className="px-3 py-1 text-sm rounded bg-[#333] text-gray-300 hover:bg-[#444] disabled:opacity-50 disabled:cursor-not-allowed"
            >
              Previous
            </button>

            <button
              onClick={() =>
                onPageChange?.(Math.min(totalPages, currentPage + 1))
              }
              disabled={currentPage === totalPages}
              className="px-3 py-1 text-sm rounded bg-[#333] text-gray-300 hover:bg-[#444] disabled:opacity-50 disabled:cursor-not-allowed"
            >
              Next
            </button>
          </div>
        </div>
      )}
    </Card>
  );
}
